package net.saksolm.monsterexpansion.screen.entry;

import net.minecraft.world.item.ItemStack;

public class DropEntry {
    public final ItemStack item;
    public final int rarityStars;
    public final String dropRange;
    public final String dropChance;
    public final boolean isTailDrop;

    public DropEntry(ItemStack item, int rarityStars, String dropRange, String dropChance) {
        this.item = item;
        this.rarityStars = rarityStars;
        this.dropRange = dropRange;
        this.dropChance = dropChance;
        this.isTailDrop = false;
    }

